        if (!out) {
            Py_DECREF(arr);
            return PyErr_NoMemory();
        }
        memcpy(out, PyArray_DATA(arr), (size_t)n * sizeof(double));
        Py_DECREF(arr);
    } else {
        PyObject *fast = PySequence_Fast(obj, "expected a 1-D sequence");
        if (!fast)
            return NULL;
        n = PySequence_Fast_GET_SIZE(fast);
        out = (double *)malloc((size_t)n * sizeof(double));
        if (!out) {
            Py_DECREF(fast);
            return PyErr_NoMemory();
